Func<dynamic, Context, CancellationToken, Task> HandleAsync = async (view, ctx, ct) =>
{
    if (view.Host is not Orc.Game.Cards.UnitCard self) { return; }
    if (!self.TryGetData<Orc.Game.Cards.UnitStateData>(out var selfState) || selfState.IsDestroyed) { return; }

    // 目标侧单命中：只有「本卡被攻击」才改写（HQ 目标不进入）。
    if (view.Target is not Orc.Core.Ref<Orc.Core.Entity> targetRef || !targetRef.IsAlive) { return; }
    if (!object.ReferenceEquals(targetRef.Value, self)) { return; }

    if (view.Attacker is not Orc.Core.Ref<Orc.Core.Entity> attackerRef || !attackerRef.IsAlive) { return; }
    if (attackerRef.Value is not Orc.Game.Cards.UnitCard attacker) { return; }
    if (!attacker.TryGetData<Orc.Game.Cards.UnitStateData>(out _)) { return; }

    if (view.Resolution is not Orc.Game.Commanding.AttackDamageResolution resolution || resolution.IsRewritten) { return; }

    var runtime = Orc.Game.Effects.EffectRuntime.ResolveFor(self);
    if (runtime is null) { return; }

    // 先资格（combat.counter.eligibility 判定器通道——豁免约束改写）。
    if (!runtime.Judge(Orc.Game.Judicators.JudicatorNames.CombatCounterEligibility, attacker, self)) { return; }

    // 后条件（combat.ambush.condition 判定器通道——单源）。
    if (!runtime.Judge(Orc.Game.Judicators.JudicatorNames.CombatAmbushCondition, self, attacker)) { return; }

    resolution.MarkRewritten();

    // 改写方自己执行死亡（经死亡动作走完整两端：触发端 → 处理端），随后置「已完整处置」。
    await Orc.Game.Cards.KeywordEffectActionFace.DeathAsync(
        self, attacker, self, view.TriggerCard as Orc.Cards.Card, ct);
    resolution.MarkHandled();
};
